import json,sys
d=json.load(sys.stdin)
s=d['components']['schemas']
for k in ['CommitmentRequest','Verdict','EpisodeView','JurorView','OperationView','ForumSendMessage','RevealRequest' ]:
    if k in s: print(k, json.dumps(s[k],indent=1))
print('---paths---')
for p,v in d['paths'].items():
    for m,op in v.items():
        print(m.upper(),p,'->',op.get('operationId'), '|', op.get('description','')[:200])
"

